c.python:
class Solution:
    def maxNumber(self, n: int) -> int:
        x = 0
        for b in range(n.bit_length()):
            if b < n.bit_length() - 1:
                x |= 1 << b
        return x

c.cpp:
class Solution {
public:
    long long maxNumber(long long n) {
        long long x = 0;
        for (int b = 0; (1LL << b) <= n; b++)
            if ((1LL << (b + 1)) <= n) x |= 1LL << b;
        return x;
    }
};

